create table if not exists public.student_skill_records (id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,skill_name text not null check (char_length(btrim(skill_name)) between 1 and 140),skill_category text not null default 'general',proficiency_level smallint not null check (proficiency_level between 1 and 5),evidence text,assessed_on date not null default current_date,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.student_cocurricular_activities (id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,activity_name text not null check (char_length(btrim(activity_name)) between 1 and 160),activity_category text not null default 'general',participation_role text,achievement text,points numeric(8,2) not null default 0 check (points >= 0),event_date date not null default current_date,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.student_competency_records (id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,competency_name text not null check (char_length(btrim(competency_name)) between 1 and 160),competency_area text not null default 'general',proficiency_level smallint not null check (proficiency_level between 1 and 5),assessment_method text not null default 'teacher_review',evidence text,notes text,assessed_on date not null default current_date,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.student_progress_history (id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,progress_type text not null check (progress_type in ('academic','attendance','skill','behaviour','wellbeing','general')),title text not null check (char_length(btrim(title)) between 1 and 180),details text,observed_on date not null default current_date,related_record_id uuid,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create index if not exists student_skill_records_institution_student_idx on public.student_skill_records(institution_id,student_id,assessed_on desc);
create index if not exists student_cocurricular_activities_institution_student_idx on public.student_cocurricular_activities(institution_id,student_id,event_date desc);
create index if not exists student_competency_records_institution_student_idx on public.student_competency_records(institution_id,student_id,assessed_on desc);
create index if not exists student_progress_history_institution_student_idx on public.student_progress_history(institution_id,student_id,observed_on desc);
do $$ declare t text; begin foreach t in array array['student_skill_records','student_cocurricular_activities','student_competency_records','student_progress_history'] loop execute format('alter table public.%I enable row level security',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);execute format('create policy %I on public.%I for select to authenticated using (has_institution_role(institution_id, ARRAY[''owner'',''admin'']) OR EXISTS (SELECT 1 FROM public.student_care_access a WHERE a.institution_id = %I.institution_id AND a.user_id = auth.uid() AND a.area = ''discipline'' AND a.can_read))',t||'_select',t,t);execute format('create policy %I on public.%I for insert to authenticated with check (created_by = auth.uid() AND (has_institution_role(institution_id, ARRAY[''owner'',''admin'']) OR EXISTS (SELECT 1 FROM public.student_care_access a WHERE a.institution_id = %I.institution_id AND a.user_id = auth.uid() AND a.area = ''discipline'' AND a.can_write)))',t||'_insert',t,t);execute format('create policy %I on public.%I for update to authenticated using (has_institution_role(institution_id, ARRAY[''owner'',''admin'']) OR EXISTS (SELECT 1 FROM public.student_care_access a WHERE a.institution_id = %I.institution_id AND a.user_id = auth.uid() AND a.area = ''discipline'' AND a.can_write)) with check (has_institution_role(institution_id, ARRAY[''owner'',''admin'']) OR EXISTS (SELECT 1 FROM public.student_care_access a WHERE a.institution_id = %I.institution_id AND a.user_id = auth.uid() AND a.area = ''discipline'' AND a.can_write))',t||'_update',t,t,t);execute format('create policy %I on public.%I for delete to authenticated using (has_institution_role(institution_id, ARRAY[''owner'',''admin'']))',t||'_delete',t);end loop;end $$;